// Core tests of the small models compiled into the core (layout/model.h, tables generated by
// tools/gen_model_tables.py; small models 2250-2299).
#include "check.h"

#include "common/utf8.h"
#include "layout/features.h"
#include "layout/model.h"
#include "layout/page.h"
#include "layout/pipeline.h"

#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <string_view>
#include <vector>

using namespace RayoPdf;
using namespace RayoPdf::Layout;

namespace {

// RawScore gives LightGBM's raw scores of the model's 64 check vectors (eval/models/*.meta.json).
void TestCheckScores(const TreeModel& model, int code) {
    bool same = model.checkCount == 64;
    for (uint32_t i = 0; i < model.checkCount; ++i) {
        const double score = RawScore(model, model.checkFeatures + size_t(i) * model.featureCount);
        same = same && std::fabs(score - model.checkScores[i]) <= 1e-9;
    }
    RAYOPDF_CHECK(same, code);
}

// Every split names a feature of the model and has its children inside its tree, after itself
// (so every walk ends at a leaf).
void TestTrees(const TreeModel& model, int code) {
    bool valid = model.treeCount > 0 && model.trees[0] == 0;
    for (uint32_t t = 0; t < model.treeCount && valid; ++t) {
        const uint32_t size = model.trees[t + 1] - model.trees[t];
        valid = model.trees[t + 1] > model.trees[t];
        const TreeNode* tree = model.nodes + model.trees[t];
        for (uint32_t i = 0; i < size && valid; ++i) {
            if (tree[i].feature < 0) continue;
            valid = uint32_t(tree[i].feature) < model.featureCount && tree[i].left > i && tree[i].left < size &&
                    tree[i].right > i && tree[i].right < size;
        }
    }
    RAYOPDF_CHECK(valid, code);
}

// Appends `text` to `page` as upright glyphs of `size` points from (x, y), each half an em wide; a
// space is a space glyph; `bold` sets every glyph bold.
void AddText(PageData& page, std::string_view text, float x, float y, float size, bool bold = false) {
    size_t at = 0;
    uint32_t cp = 0;
    size_t length = 0;
    while (Utf8::Decode(text, at, cp, length)) {
        Glyph g;
        const float w = 0.5f * size;
        g.u0 = x, g.u1 = x + w, g.vb = y - 0.2f * size, g.vt = y + 0.8f * size, g.v = y;
        g.size = size;
        g.text = static_cast<uint32_t>(page.text.size());
        page.text.append(text.substr(at, length));
        g.textLength = static_cast<uint16_t>(length);
        if (cp == ' ') g.flags |= kGlyphSpace;
        if (bold) g.flags |= kGlyphBold;
        page.glyphs.push_back(g);
        x += w;
        at += length;
    }
}

PageData NewPage() {
    PageData page;
    page.number = 1;
    page.width = 612;
    page.height = 792;
    return page;
}

// Converting `pages`: the Markdown, and the edge-row model's raw score of the edge row whose text
// is `row` when the rules kept it (-INFINITY when they removed it or no such row was examined).
struct Converted {
    std::string md;
    double score = -INFINITY;
};

Converted Convert(std::vector<PageData> pages, const char* row, Furniture furniture = Furniture::Drop) {
    struct Context {
        const char* row;
        double score;
    } context{row, -INFINITY};
    FeatureSink sink;
    sink.context = &context;
    sink.edgeRow = [](void* c, uint32_t, const float* f, float, float, float, float, std::string_view text, bool removed) {
        Context& ctx = *static_cast<Context*>(c);
        if (text == ctx.row && !removed) ctx.score = RawScore(kEdgeRowModel, f);
    };
    OutputSettings output;
    output.features = &sink;
    output.furniture = furniture;
    Converted out;
    ConvertReport report;
    std::vector<PageTextQuality> quality(pages.size());
    ConvertPages(pages, quality, {}, false, out.md, report, nullptr, nullptr, MathMode::Unicode, nullptr, nullptr, &output);
    out.score = context.score;
    if (std::getenv("RAYOPDF_TEST_VERBOSE")) std::fprintf(stderr, "--- %s: %.3f\n%s", row, out.score, out.md.c_str());
    return out;
}

// Body lines of 10 points from `top` down, `count` of them `pitch` apart, from x = 72, about 105
// characters (525 points) long.
void AddBody(PageData& page, int count, float top, float pitch) {
    for (int i = 0; i < count; ++i)
        AddText(page,
                "Body line " + std::to_string(i) +
                    " of the running text goes on here and so on and so on and so on and so on and so on and so on.",
                72, top - pitch * i, 10);
}

// A row the edge-row model takes for furniture ("Overview" at the head of a page, 1.15 body sizes,
// 2.4 ems above the text, kept by the rules) is left out, and nothing else changes: the output is
// that of the page with the row kept as text (--furniture=keep), less the row's own block.
void TestModelRemovalIsLocal() {
    std::vector<PageData> pages{NewPage()};
    AddText(pages[0], "Overview", 72, 775, 11.5f);
    AddBody(pages[0], 51, 775 - 0.2f * 11.5f - 24 - 8, 12);
    const Converted dropped = Convert(pages, "Overview");
    const Converted kept = Convert(pages, "Overview", Furniture::Keep);
    const size_t first = kept.md.find("Overview");
    const size_t rest = kept.md.find("\n\n", first);
    RAYOPDF_CHECK(dropped.score >= kEdgeRowRawTau && dropped.md.find("Overview") == std::string::npos &&
                      first != std::string::npos && rest != std::string::npos &&
                      dropped.md == kept.md.substr(0, kept.md.rfind('\n', first) + 1) + kept.md.substr(rest + 2),
                  2254);
}

// A caption under a figure at the foot of a sparse page stays, though the edge-row model scores it
// furniture: the rules keep it (the figure sets it close), and the semantics make it a caption.
// It ends in no full stop, so the guard of rows that end a sentence does not decide it.
void TestCaptionGuard() {
    std::vector<PageData> pages{NewPage()};
    AddBody(pages[0], 3, 740, 24);
    ImageBox image;
    image.x0 = 100, image.x1 = 500, image.y0 = 27, image.y1 = 400;
    pages[0].images.push_back(image);
    AddText(pages[0], "Label 0", 110, 45.4f, 10);
    AddText(pages[0], "Label 1", 200, 45.4f, 10);
    AddText(pages[0], "Fig. 4. Test Results on the DVD dataset", 150, 20, 8);
    const Converted c = Convert(pages, "Fig. 4. Test Results on the DVD dataset");
    RAYOPDF_CHECK(c.score >= kEdgeRowRawTau && c.md.find("Fig. 4. Test Results") != std::string::npos, 2255);
}

// A one-line paragraph at the head of a page, over a heading set apart from it, stays though the
// edge-row model scores it furniture: it ends a sentence, and the model never takes such a row
// (DocLayNet's training pages hardly show one, so the model cannot learn it).
void TestSentenceGuard() {
    std::vector<PageData> pages{NewPage()};
    AddText(pages[0], "Sentinel start C01.", 34, 750, 10);
    AddText(pages[0], "Headings", 34, 715, 20, true);
    AddBody(pages[0], 40, 680, 12);
    const Converted c = Convert(pages, "Sentinel start C01.");
    RAYOPDF_CHECK(c.score >= kEdgeRowRawTau && c.md.find("Sentinel start C01.") != std::string::npos, 2257);
}

} // namespace

int main() {
    RAYOPDF_CHECK(kEdgeRowModel.featureCount == uint32_t(kEdgeRowFeatures), 2252);
    TestCheckScores(kEdgeRowModel, 2252);
    TestTrees(kEdgeRowModel, 2253);
    // The raw threshold is τ's log-odds.
    RAYOPDF_CHECK(std::fabs(1 / (1 + std::exp(-kEdgeRowRawTau)) - kEdgeRowTau) <= 1e-12, 2253);
    TestModelRemovalIsLocal();
    TestCaptionGuard();
    TestSentenceGuard();
    return 0;
}
